import React from 'react';

const Aprendizajes = () => {
    return (
        <section>
            <h2>Aprendizajes Obtenidos</h2>
            <p>
                El desarrollo de esta propuesta permite comprender que la investigación histórica no debe limitarse al ámbito académico, sino que puede transformarse en herramientas innovadoras de educación y sensibilización social.
            </p>
            <p>
                Entre los principales aprendizajes obtenidos se encuentra la importancia de fortalecer la memoria histórica, promover valores democráticos, conectar la historia con la educación cívica y utilizar medios digitales como instrumentos eficaces para acercar el conocimiento a la población joven.
            </p>
            <p>
                Asimismo, la propuesta demuestra que la colaboración entre academia, gobierno, sector privado y sociedad civil puede generar productos con mayor alcance, pertinencia y utilidad social.
            </p>
        </section>
    );
};

export default Aprendizajes;
